//! D02 end-to-end vectors (`ffw-7s0`).
//!
//! `tests/d02/vectors.json` is generated by the independent Python reference
//! (`tests/d02/generate.py`), never by this crate. This executor runs every vector through the public
//! API and prints one `D02-OBSERVED {json}` line per case for the Python judge
//! (`tests/d02/run_cases.py --judge`). It also self-checks the pure numeric kinds (designs, section
//! responses, DC rejection, limiter, validation); scenario traces are judged only by the Python
//! side, against closed forms and invariants that it computes itself.
//!
//! Run with `cargo test -p franken-dsp --test d02_vectors -- --nocapture`. Override the vector path
//! with `FFW_D02_VECTORS`.

use franken_board_profile::{BoardProfile, synthetic_test_fixture_catalog};
use franken_dsp::StereoAudioBlock;
use franken_dsp::protection::{
    Admission, BiquadSpec, BoardCalibration, BoardStatus, DcRejector, Limiter, ProtectedBoardDsp,
    ProtectedOutput, ProtectionError, Section, SourceEvent, butterworth2_highpass,
    butterworth2_lowpass, smoothing_coefficient,
};
use serde_json::{Value, json};

const FS: f64 = 48_000.0;

fn field<'a>(value: &'a Value, key: &str) -> &'a Value {
    value
        .get(key)
        .unwrap_or_else(|| panic!("vector field `{key}` is missing"))
}

fn str_of<'a>(value: &'a Value, key: &str) -> &'a str {
    field(value, key)
        .as_str()
        .unwrap_or_else(|| panic!("vector field `{key}` is not a string"))
}

fn f64_of(value: &Value, key: &str) -> f64 {
    field(value, key)
        .as_f64()
        .unwrap_or_else(|| panic!("vector field `{key}` is not a number"))
}

fn usize_of(value: &Value, key: &str) -> usize {
    let n = field(value, key)
        .as_u64()
        .unwrap_or_else(|| panic!("vector field `{key}` is not an unsigned integer"));
    usize::try_from(n).unwrap_or_else(|_| panic!("vector field `{key}` does not fit usize"))
}

fn fixture(model: &str) -> BoardProfile {
    synthetic_test_fixture_catalog()
        .into_iter()
        .find(|profile| profile.model_number == model)
        .unwrap_or_else(|| panic!("no synthetic fixture board `{model}`"))
}

/// Substitute the placeholder profile binding and parse the calibration document.
fn bind(value: &Value, profile: &BoardProfile) -> Result<BoardCalibration, ProtectionError> {
    let id = serde_json::to_string(&profile.profile_id).expect("id");
    let digest = serde_json::to_string(&profile.integrity_sha256).expect("digest");
    let text = value
        .to_string()
        .replace("\"@profile_id\"", &id)
        .replace("\"@profile_digest\"", &digest);
    BoardCalibration::from_json(&text)
}

fn status_label(status: &BoardStatus) -> String {
    match status {
        BoardStatus::Active => "active".to_string(),
        BoardStatus::FailMuted(error) => format!("fail_muted:{}", error.code()),
        BoardStatus::Faulted(fault) => format!("faulted:{}:{}", fault.code(), fault.channel()),
    }
}

fn result_label<T>(result: Result<T, ProtectionError>) -> String {
    match result {
        Ok(_) => "ok".to_string(),
        Err(error) => error.code().to_string(),
    }
}

fn error_json(error: &ProtectionError) -> Value {
    json!({"status": "fail_muted", "error": error.code(), "channel": error.channel(),
        "section": error.section(), "parameter": error.parameter()})
}

fn within(got: f64, want: f64, tolerance: f64) -> bool {
    (got - want).abs() <= tolerance
}

/// First index where two sequences differ by more than `tolerance`.
fn first_difference(got: &[f64], want: &[f64], tolerance: f64) -> Option<String> {
    if got.len() != want.len() {
        return Some(format!("length {} != {}", got.len(), want.len()));
    }
    got.iter()
        .zip(want.iter())
        .position(|(g, w)| !within(*g, *w, tolerance))
        .map(|i| format!("index {i}: got {}, want {}", got[i], want[i]))
}

fn numbers(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .expect("array")
        .iter()
        .map(|v| v.as_f64().expect("number"))
        .collect()
}

fn run_design(case: &Value) -> (Value, Option<String>) {
    let fc = f64_of(case, "fc_hz");
    let spec = match str_of(case, "filter") {
        "lp" => butterworth2_lowpass(fc, FS),
        _ => butterworth2_highpass(fc, FS),
    };
    let got = [spec.b0, spec.b1, spec.b2, spec.a1, spec.a2];
    let expect = field(case, "expect");
    let want = ["b0", "b1", "b2", "a1", "a2"].map(|k| f64_of(expect, k));
    let problem = got
        .iter()
        .zip(want.iter())
        .position(|(g, w)| !within(*g, *w, 1.0e-12 * w.abs().max(1.0)))
        .map(|i| format!("coefficient {i}: got {}, want {}", got[i], want[i]));
    (
        json!({"coefficients": {"b0": got[0], "b1": got[1], "b2": got[2], "a1": got[3], "a2": got[4]}}),
        problem,
    )
}

fn run_section_response(case: &Value) -> (Value, Option<String>) {
    let spec: BiquadSpec = serde_json::from_value(field(case, "spec").clone()).expect("spec");
    let mut section = Section::from_spec(&spec).expect("section is admissible");
    let impulse = str_of(case, "drive") == "impulse";
    let y: Vec<f64> = (0..usize_of(case, "length"))
        .map(|n| {
            let x = if impulse && n > 0 { 0.0 } else { 1.0 };
            f64::from(section.process(x))
        })
        .collect();
    let problem = first_difference(
        &y,
        &numbers(field(case, "expect")),
        f64_of(case, "tolerance"),
    );
    (json!({"y": y}), problem)
}

fn run_dc(case: &Value) -> (Value, Option<String>) {
    let mut dc = DcRejector::new(f64_of(case, "hz"), FS);
    let x = f64_of(case, "x") as f32;
    let y: Vec<f64> = (0..usize_of(case, "length"))
        .map(|_| f64::from(dc.process(x)))
        .collect();
    let problem = first_difference(
        &y,
        &numbers(field(case, "expect")),
        f64_of(case, "tolerance"),
    );
    (json!({"y": y}), problem)
}

fn run_limiter(case: &Value) -> (Value, Option<String>) {
    let mut limiter = Limiter::new(
        f64_of(case, "threshold") as f32,
        smoothing_coefficient(f64_of(case, "attack_ms"), FS),
        smoothing_coefficient(f64_of(case, "release_ms"), FS),
    );
    let (mut gains, mut outs) = (Vec::new(), Vec::new());
    for segment in field(case, "segments").as_array().expect("segments") {
        let value = segment[0].as_f64().expect("value") as f32;
        for _ in 0..segment[1].as_u64().expect("count") {
            let out = limiter.process(value);
            gains.push(f64::from(limiter.gain()));
            outs.push(f64::from(out));
        }
    }
    let tolerance = f64_of(case, "tolerance");
    let problem = first_difference(&gains, &numbers(field(case, "expect_gain")), tolerance)
        .map(|m| format!("gain {m}"))
        .or_else(|| {
            first_difference(&outs, &numbers(field(case, "expect_out")), tolerance)
                .map(|m| format!("out {m}"))
        });
    (json!({"gain": gains, "out": outs}), problem)
}

fn run_validation(case: &Value) -> (Value, Option<String>) {
    let profile = fixture(str_of(case, "fixture"));
    let observed = match bind(field(case, "calibration"), &profile) {
        Err(error) => error_json(&error),
        Ok(calibration) => {
            let dsp =
                ProtectedBoardDsp::admit(&profile, Some(&calibration), Admission::HostSimulation);
            match dsp.status() {
                BoardStatus::FailMuted(error) => error_json(&error),
                _ => json!({"status": "active"}),
            }
        }
    };
    let problem = (observed != *field(case, "expect"))
        .then(|| format!("expected {}, observed {observed}", field(case, "expect")));
    (observed, problem)
}

fn block_for(kind: &str, amplitude: f32) -> StereoAudioBlock {
    let mut block = StereoAudioBlock::silence(0);
    if kind == "nyquist_left" {
        for (i, sample) in block.left.iter_mut().enumerate() {
            *sample = if i.is_multiple_of(2) {
                amplitude
            } else {
                -amplitude
            };
        }
    }
    block
}

fn peak(out: &ProtectedOutput, channel: usize) -> i32 {
    out.samples[channel][..out.frames]
        .iter()
        .map(|&s| i32::from(s).abs())
        .max()
        .unwrap_or(0)
}

fn run_scenario(case: &Value) -> (Value, Option<String>) {
    let profile = fixture(str_of(case, "fixture"));
    let admission = if str_of(case, "admission") == "production" {
        Admission::Production
    } else {
        Admission::HostSimulation
    };
    let calibration = field(case, "calibration_present")
        .as_bool()
        .expect("bool")
        .then(|| bind(field(case, "calibration"), &profile).expect("scenario calibration parses"));
    let mut dsp = ProtectedBoardDsp::admit(&profile, calibration.as_ref(), admission);
    let mut trace: Vec<Value> = Vec::new();
    for op in field(case, "ops").as_array().expect("ops") {
        let name = op[0].as_str().expect("op name");
        let mut blocks: Vec<Value> = Vec::new();
        let result = match name {
            "unmute" => result_label(dsp.set_muted(false)),
            "mute" => result_label(dsp.set_muted(true)),
            "gain" => {
                dsp.set_user_gain(op[1].as_f64().expect("gain") as f32);
                "ok".to_string()
            }
            "event" => {
                dsp.on_source_event(match op[1].as_str().expect("event") {
                    "seek" => SourceEvent::Seek,
                    "reconnect" => SourceEvent::Reconnect,
                    _ => SourceEvent::SourceReplaced,
                });
                "ok".to_string()
            }
            "switch" => {
                let alternate = field(
                    field(case, "alternates"),
                    op[1].as_str().expect("alternate"),
                );
                let candidate = bind(alternate, &profile).expect("alternate parses");
                result_label(dsp.request_profile_switch(
                    &profile,
                    &candidate,
                    Admission::HostSimulation,
                ))
            }
            "clear_fault" => result_label(dsp.clear_fault()),
            "drive" => {
                let input = block_for(
                    op[1].as_str().expect("kind"),
                    op[2].as_f64().expect("amp") as f32,
                );
                for _ in 0..op[3].as_u64().expect("blocks") {
                    let mut out = ProtectedOutput::new();
                    let report = dsp.render_into(&input, &mut out);
                    let peaks: Vec<i32> = (0..out.channels).map(|c| peak(&out, c)).collect();
                    blocks.push(json!({"status": status_label(&report.status),
                        "applied_gain": report.applied_gain, "source_fade": report.source_fade,
                        "peak": peaks, "thermal_max": report.max_thermal_level,
                        "limiter_min": report.min_limiter_gain, "clipped": report.clipped_samples,
                        "scaled": report.thermal_scaled_samples}));
                }
                "ok".to_string()
            }
            other => panic!("unknown scenario op `{other}`"),
        };
        let thermal: Vec<f64> = (0..dsp.channel_count())
            .map(|c| f64::from(dsp.thermal_level(c).unwrap_or(0.0)))
            .collect();
        let limiter: Vec<f64> = (0..dsp.channel_count())
            .map(|c| f64::from(dsp.limiter_gain(c).unwrap_or(1.0)))
            .collect();
        trace.push(
            json!({"op": name, "result": result, "status": status_label(&dsp.status()),
            "thermal": thermal, "limiter": limiter, "applied_gain": dsp.applied_gain(),
            "user_gain": dsp.user_gain(), "muted": dsp.is_muted(),
            "pending": dsp.has_pending_switch(), "blocks": blocks}),
        );
    }
    let problem = trace.is_empty().then(|| "empty scenario".to_string());
    (json!({"trace": trace}), problem)
}

fn run_case(case: &Value) -> (Value, Option<String>) {
    let (mut observed, problem) = match str_of(case, "kind") {
        "design" => run_design(case),
        "section_response" => run_section_response(case),
        "dc_response" => run_dc(case),
        "limiter_response" => run_limiter(case),
        "validation" => run_validation(case),
        "scenario" => run_scenario(case),
        other => panic!("unknown vector kind `{other}`"),
    };
    if let Some(map) = observed.as_object_mut() {
        map.insert("id".to_string(), json!(str_of(case, "id")));
        map.insert("kind".to_string(), json!(str_of(case, "kind")));
    }
    (observed, problem)
}

fn load_vectors() -> Value {
    let path = std::env::var("FFW_D02_VECTORS").unwrap_or_else(|_| {
        format!(
            "{}/../../tests/d02/vectors.json",
            env!("CARGO_MANIFEST_DIR")
        )
    });
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!("cannot read D02 vectors at {path}: {e} (generate: tests/d02/run_cases.py --write-vectors)")
    });
    let doc: Value = serde_json::from_str(&text).expect("vectors.json parses");
    assert_eq!(doc["schema"], "ffw.d02.vectors.v1");
    doc
}

#[test]
fn d02_vectors_match_the_independent_reference() {
    let doc = load_vectors();
    let cases = doc["cases"].as_array().expect("cases array");
    assert!(
        cases.len() >= 60,
        "suspiciously few vectors: {}",
        cases.len()
    );
    let mut failures: Vec<String> = Vec::new();
    for case in cases {
        let (observed, problem) = run_case(case);
        println!("D02-OBSERVED {observed}");
        if let Some(message) = problem {
            let line = format!("{}: {message}", str_of(case, "id"));
            println!("D02-DIVERGENCE {line}");
            failures.push(line);
        }
    }
    println!(
        "D02-SUMMARY cases={} failures={}",
        cases.len(),
        failures.len()
    );
    assert!(
        failures.is_empty(),
        "{} of {} D02 vectors diverged from the reference; first: {}",
        failures.len(),
        cases.len(),
        failures[0]
    );
}

/// Control: the comparison is not vacuous. A planted wrong expectation must be reported.
#[test]
fn a_planted_wrong_expectation_is_detected() {
    let doc = load_vectors();
    let cases = doc["cases"].as_array().expect("cases array");
    let case = cases
        .iter()
        .find(|c| str_of(c, "kind") == "section_response")
        .expect("a section response vector");
    assert!(
        run_case(case).1.is_none(),
        "the unmodified vector must pass"
    );
    let mut corrupted = case.clone();
    let mut expect = numbers(field(case, "expect"));
    expect[100] += 1.0e-3;
    corrupted["expect"] = json!(expect);
    let problem = run_case(&corrupted).1.expect("corruption must be detected");
    assert!(problem.contains("index 100"), "{problem}");

    let validation = cases
        .iter()
        .find(|c| str_of(c, "kind") == "validation" && field(c, "expect")["status"] == "active")
        .expect("a passing validation vector");
    let mut wrong = validation.clone();
    wrong["expect"] = json!({"status": "fail_muted", "error": "unstable", "channel": 0,
        "section": 0, "parameter": null});
    assert!(run_case(&wrong).1.is_some());
}
